/// Builds the composite propagator for `kinds`. `extra` supplies propagators the template does
/// not ship (matched by [`PropagatorKind::Other`] name); unknown names → `CONFIG`.
pub fn build_propagator(
    kinds: &[PropagatorKind],
    mut extra: HashMap<String, BoxedPropagator>,
) -> Result<TextMapCompositePropagator> {
    let mut list: Vec<BoxedPropagator> = Vec::with_capacity(kinds.len());
    for kind in kinds {
        list.push(match kind {
            PropagatorKind::TraceContext => Box::new(TraceContextPropagator::new()),
            PropagatorKind::Baggage => Box::new(BaggagePropagator::new()),
            PropagatorKind::B3 => Box::new(B3Propagator::single()),
            PropagatorKind::B3Multi => Box::new(B3Propagator::multi()),
            PropagatorKind::Other(name) => extra.remove(name).ok_or_else(|| {
                Error::config(format!(
                    "propagator {name:?} is not supported by this package"
                ))
            })?,
        });
    }
    Ok(TextMapCompositePropagator::new(list))
}

